catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var ACTION_VAR = 'action';
    var DELETE_VALUE = 'delete';


    var actionVal = (g_form.getValue(ACTION_VAR) || '').toString().toLowerCase();
    if (actionVal !== DELETE_VALUE) {
        return;
    }
    if (!newValue) {
        g_form.setValue('reason_code_label', '');
        g_form.setValue('reason_code_type', '');
        g_form.setValue('reason_description', '');
        g_form.setValue('reason_dashboard_group', '');
        return;
    }

    var ga = new GlideAjax('HSBCTradeTaskUtils');
    ga.addParam('sysparm_name', 'getReasonCodeDetails');
    ga.addParam('sysparm_sys_id', newValue);
    ga.getXMLAnswer(handleResponse);
}

function handleResponse(answer) {
    if (!answer) return;
    var data;
    try {
        data = JSON.parse(answer);
    } catch (e) {
        return;
    }

    if (data.reason_code_label != null) g_form.setValue('reason_code_label', data.reason_code_label);
    if (data.reason_code_type != null) g_form.setValue('reason_code_type', data.reason_code_type);
    if (data.reason_description != null) g_form.setValue('reason_description', data.reason_description);
    if (data.reason_dashboard_group != null) g_form.setValue('reason_dashboard_group', data.reason_dashboard_group);

}
